343		raw, err := base64.StdEncoding.DecodeString(s)
344		if err != nil {
345			return nil, err
346		}
347		if base64.StdEncoding.EncodeToString(raw) != s {
348			return nil, fmt.Errorf("non-canonical base64")
349		}
350		return raw, nil
351	}
